    fn build_filter_select(&self) -> Select<Entity> {
        let mut select = Entity::find();
        for predicate in &self.predicates {
            select = select.filter(Self::predicate_condition(predicate));
        }
        select
    }

    fn apply_order(&self, mut select: Select<Entity>) -> Select<Entity> {
        for order in &self.orders {
            match order {
                ScalarFixtureOrder::IdAsc => select = select.order_by_asc(Column::Id),
                ScalarFixtureOrder::IdDesc => select = select.order_by_desc(Column::Id),
                ScalarFixtureOrder::ExternalIdAsc => {
                    select = select.order_by_asc(Column::ExternalId)
                }
                ScalarFixtureOrder::ExternalIdDesc => {
                    select = select.order_by_desc(Column::ExternalId)
                }
                ScalarFixtureOrder::SmallValueAsc => {
                    select = select.order_by_asc(Column::SmallValue)
                }
                ScalarFixtureOrder::SmallValueDesc => {
                    select = select.order_by_desc(Column::SmallValue)
                }
                ScalarFixtureOrder::IntValueAsc => select = select.order_by_asc(Column::IntValue),
                ScalarFixtureOrder::IntValueDesc => select = select.order_by_desc(Column::IntValue),
                ScalarFixtureOrder::BigValueAsc => select = select.order_by_asc(Column::BigValue),
                ScalarFixtureOrder::BigValueDesc => select = select.order_by_desc(Column::BigValue),
                ScalarFixtureOrder::FloatValueAsc => {
                    select = select.order_by_asc(Column::FloatValue)
                }
                ScalarFixtureOrder::FloatValueDesc => {
                    select = select.order_by_desc(Column::FloatValue)
                }
                ScalarFixtureOrder::DoubleValueAsc => {
                    select = select.order_by_asc(Column::DoubleValue)
                }
                ScalarFixtureOrder::DoubleValueDesc => {
                    select = select.order_by_desc(Column::DoubleValue)
                }
                ScalarFixtureOrder::PayloadAsc => select = select.order_by_asc(Column::Payload),
                ScalarFixtureOrder::PayloadDesc => select = select.order_by_desc(Column::Payload),
                ScalarFixtureOrder::MetadataAsc => select = select.order_by_asc(Column::Metadata),
                ScalarFixtureOrder::MetadataDesc => select = select.order_by_desc(Column::Metadata),
                ScalarFixtureOrder::AmountAsc => select = select.order_by_asc(Column::Amount),
                ScalarFixtureOrder::AmountDesc => select = select.order_by_desc(Column::Amount),
                ScalarFixtureOrder::LocalTimeAsc => select = select.order_by_asc(Column::LocalTime),
                ScalarFixtureOrder::LocalTimeDesc => {
                    select = select.order_by_desc(Column::LocalTime)
                }
                ScalarFixtureOrder::EventTimeAsc => select = select.order_by_asc(Column::EventTime),
                ScalarFixtureOrder::EventTimeDesc => {
                    select = select.order_by_desc(Column::EventTime)
                }
            }
        }
        select
    }

    fn build_select(&self) -> Select<Entity> {
        let mut select = self.apply_order(self.build_filter_select());
        if let Some(limit) = self.limit {
            select = select.limit(limit);
        }
        if let Some(offset) = self.offset {
            select = select.offset(offset);
        }
        select
    }

    /// Converts this typed query into the backend-native SeaORM select.
    /// Predicates, soft-delete scope, ordering and pagination are preserved.
    pub fn into_select(self) -> Select<Entity> {
        self.build_select()
    }

