    pub async fn sum_small_value_by_id(self) -> anyhow::Result<Vec<(String, i16)>> {
        let db = self.repo.read_db_from(self.read_source)?;
        let sum = if db.get_database_backend() == DatabaseBackend::Postgres {
            Expr::col(Column::SmallValue).sum().cast_as("SMALLINT")
        } else {
            Expr::col(Column::SmallValue).sum()
        };
        let rows = self
            .build_filter_select()
            .select_only()
            .column(Column::Id)
            .column_as(sum, "roze_sum")
            .group_by(Column::Id)
            .into_tuple::<(String, Option<i16>)>()
            .all(&db)
            .await?;
        Ok(rows
            .into_iter()
            .map(|(group, value)| (group, value.unwrap_or_default()))
            .collect())
    }

